            dFlash(pFlash(), [[L('Grok può generare immagini', 'Grok can generate images'), true], [L('Lo stile informale garantisce accuratezza', 'An informal style guarantees accuracy'), false], [L('Alcune funzioni richiedono abbonamento', 'Some features need a subscription'), true], [L('Grok non sa analizzare foto', 'Grok cannot analyse photos'), false]], L('Strumenti potenti, giudizio critico.', 'Powerful tools, critical judgement.')),
        ]),
