            Q('p2', L('Che cosa può essere usato per addestrare Grok, secondo le impostazioni?', 'What may be used to train Grok, depending on settings?'), [L('Post pubblici e interazioni con Grok', 'Public posts and Grok interactions'), L('Le tue foto locali', 'Your local photos'), L('Le email di altri servizi', 'Emails from other services'), L('Niente mai', 'Nothing ever')], 0, L('Controlla l’opzione.', 'Check the option.')),
            Q('p3', L('Che cosa non condividere con un assistente?', 'What not to share with an assistant?'), [L('Password e segreti di lavoro', 'Passwords and work secrets'), L('Una ricetta', 'A recipe'), L('Un indovinello', 'A riddle'), L('Una domanda di storia', 'A history question')], 0, L('Regola universale.', 'Universal rule.')),
        ], task('text', L('Scrivi tre passi per proteggere la tua privacy usando Grok su X, una riga per passo con `-`, tra cui uno sull’**addestramento**.', 'Write three steps to protect your privacy using Grok on X, one line per step with `-`, including one about **training**.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre passi', 'Three steps')), re('addestr|train', L('Uno sull’addestramento', 'One about training'))], '', "- controllare nelle impostazioni privacy se i post possono addestrare Grok\n- non condividere dati personali o di lavoro nelle chat\n- valutare se rendere privato l’account"), [
            dMatch(pMatch(), [[L('Impostazioni privacy', 'Privacy settings'), L('Addestramento sì o no', 'Training yes or no')], [L('Post pubblici', 'Public posts'), L('Visibili a tutti', 'Visible to all')], [L('Account privato', 'Private account'), L('Limita chi vede', 'Limits who sees')], [L('Segreti', 'Secrets'), L('Mai nelle chat', 'Never in chats')]], L('Controllare i propri dati.', 'Controlling your data.')),
            dFlash(pFlash(), [[L('X ha un’opzione sull’uso dei post per Grok', 'X has an option on using posts for Grok'), true], [L('I post pubblici non sono mai usati da nessuno', 'Public posts are never used by anyone'), false], [L('Conviene controllare le impostazioni privacy', 'Checking privacy settings is wise'), true], [L('Le password si possono scrivere a Grok', 'Passwords can be written to Grok'), false]], L('Le tue scelte contano.', 'Your choices matter.')),
        ]),
        lesson('api', L('L’API di xAI', 'The xAI API'), [
            P('L’API di xAI permette di usare i modelli Grok nelle tue app ed è **compatibile con quella di OpenAI**: si usa il suo SDK cambiando l’indirizzo in `https://api.x.ai/v1`. La chiave si crea nella console per sviluppatori di xAI.', 'The xAI API lets you use Grok models in your apps and is **OpenAI-compatible**: you use its SDK changing the address to `https://api.x.ai/v1`. The key is created in the xAI developer console.'),
